html:
{% set company_doc = frappe.db.get_value("Company", doc.company, ["company_logo", "email", "phone_no"], as_dict=1) if doc.company else {} %}
{% set hbr = frappe.db.get_value("Home Build Request", doc.home_build_request, [
    "factory", "home_buyer", "escrow_company", "escrow_number",
    "selling_price", "customer_deposit", "end_buyer_lender"
], as_dict=1) if doc.home_build_request else {} %}
{% set manufacturer_name = frappe.db.get_value("Supplier", hbr.factory, "supplier_name") if hbr and hbr.factory else "" %}
{% set buyer_name = frappe.db.get_value("Customer", hbr.home_buyer, "customer_name") if hbr and hbr.home_buyer else "" %}
{% set escrow_name = frappe.db.get_value("Supplier", hbr.escrow_company, "supplier_name") if hbr and hbr.escrow_company else "" %}

{# Determine variant title #}
{%- if doc.home_type == "Spec" -%}
  {%- set variant_title = "Spec Home Flooring Request" -%}
{%- else -%}
  {%- set variant_title = "Customer Sold Flooring Request" -%}
{%- endif -%}

{%- macro format_currency(amount) -%}
{{ frappe.utils.fmt_money(amount, currency="USD") }}
{%- endmacro -%}

{%- macro fmt_date(d) -%}
{%- if d -%}{{ frappe.utils.formatdate(d, "MM/dd/yyyy") }}{%- endif -%}
{%- endmacro -%}

{%- macro format_phone(phone) -%}
{%- if phone -%}
{%- set digits = phone | replace("+", "") | replace("-", "") | replace(" ", "") | replace("(", "") | replace(")", "") -%}
{%- if digits | length == 10 -%}
+1 ({{ digits[:3] }}) {{ digits[3:6] }}-{{ digits[6:] }}
{%- elif digits | length == 11 and digits[0] == '1' -%}
+1 ({{ digits[1:4] }}) {{ digits[4:7] }}-{{ digits[7:] }}
{%- else -%}
{{ phone }}
{%- endif -%}
{%- endif -%}
{%- endmacro -%}

{%- macro fmt_pct(val) -%}
{%- if val is not none and val -%}{{ "%.0f" | format(val) }}%{%- else -%}0%{%- endif -%}
{%- endmacro -%}

<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">

<style>
  .inv {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif !important;
    font-weight: 500 !important; color: #000 !important;
    font-size: 13px !important; line-height: 1.2 !important; width: 100% !important;
  }
  .inv table { border-collapse: collapse !important; width: 100% !important; }
  .inv td, .inv th { padding: 0 !important; vertical-align: top !important; }
  .inv-div {
    border-top: 1px solid #ddd !important; border-bottom: none !important;
    border-left: none !important; border-right: none !important;
    height: 0 !important; margin: 32px 0 !important; background: none !important;
  }
  .lbl { font-weight: 600 !important; font-size: 13px !important; color: #000 !important; padding-bottom: 6px !important; }
  .val { font-size: 13px !important; font-weight: 500 !important; color: #333b44 !important; line-height: 1.4 !important; }
  .inv-items {
    width: 100% !important; border-collapse: separate !important; border-spacing: 0 !important;
    border-radius: 4px !important; overflow: hidden !important;
  }
  .inv-items thead th {
    background: #000 !important; color: #fff !important; font-weight: 600 !important;
    font-size: 12px !important; padding: 12px 20px !important; text-align: left !important;
    letter-spacing: 0.3px !important; border: none !important;
  }
  .inv-items thead tr th:first-child { border-top-left-radius: 4px !important; }
  .inv-items thead tr th:last-child { border-top-right-radius: 4px !important; }
  @media print { .inv-items thead { display: table-row-group !important; } }
  .inv-items tbody td {
    padding: 12px 20px !important; font-size: 12px !important; font-weight: 500 !important;
    color: #333b44 !important; border-bottom: 1px solid #e0e0e0 !important;
    vertical-align: top !important; background: #f5f5f5 !important;
  }
  .inv-items tbody td.f-lbl { font-weight: 700 !important; color: #000 !important; width: 260px !important; }
  .inv-items tbody td.f-val { font-weight: 500 !important; color: #000 !important; }
  .inv-items tbody tr:last-child td { border-bottom: none !important; }
  .inv-items tbody tr:last-child td:first-child { border-bottom-left-radius: 4px !important; }
  .inv-items tbody tr:last-child td:last-child { border-bottom-right-radius: 4px !important; }
  .no-break { page-break-inside: avoid !important; }
</style>

<div class="inv">

  <!-- ═══ HEADER ═══ -->
  <table>
    <tr>
      <td style="width: 50% !important;">
        <img src="/files/logo.png" style="height: 40px !important; object-fit: contain !important; display: block !important;" alt="Dealer Capital Resources">
      </td>
      <td style="width: 50% !important; text-align: right !important;">
        <div style="font-size: 13px !important; color: #333b44 !important;">{{ doc.name }}</div>
      </td>
    </tr>
  </table>

  <div class="inv-div"></div>

  <!-- ═══ TITLE ═══ -->
  <div style="font-size: 20px !important; font-weight: 600 !important; color: #000 !important; padding-bottom: 8px !important;">{{ variant_title }}</div>

  <!-- ═══ ADVANCE PRE-APPROVAL FLOORING INFORMATION ═══ -->
  <table class="inv-items" style="margin-top: 24px !important;">
    <thead>
      <tr><th colspan="2">Advance Pre-Approval Flooring Information</th></tr>
    </thead>
    <tbody>
      <tr>
        <td class="f-lbl">Borrower</td>
        <td class="f-val">{{ doc.applicant_name or doc.applicant or '' }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Borrower balance</td>
        <td class="f-val">{{ format_currency(doc.outstanding_loan_balance or doc.custom_borrower_balance or 0) }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Current Y/N</td>
        <td class="f-val">{{ doc.custom_current_yn or 'Yes' }}</td>
      </tr>
    </tbody>
  </table>

  <table class="inv-items" style="margin-top: 16px !important;">
    <thead>
      <tr><th colspan="2">Payee / Builder Details</th></tr>
    </thead>
    <tbody>
      <tr>
        <td class="f-lbl">Payee (Builder)</td>
        <td class="f-val">{{ doc.custom_payee_builder or manufacturer_name or '' }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Quote #</td>
        <td class="f-val">{{ doc.custom_quote_number or doc.quote_no or '' }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Projected advance amount</td>
        <td class="f-val">{{ format_currency(doc.requested_advance_amount or doc.loan_amount or 0) }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Projected advance date</td>
        <td class="f-val">{{ fmt_date(doc.advance_date_requested or doc.custom_projected_advance_date) }}</td>
      </tr>
    </tbody>
  </table>

  <!-- ═══ KEY INFORMATION — SPEC VARIANT ═══ -->
  {% if doc.home_type == "Spec" %}
  <table class="inv-items" style="margin-top: 16px !important;">
    <thead>
      <tr><th colspan="2">Key Information</th></tr>
    </thead>
    <tbody>
      <tr>
        <td class="f-lbl">Projected investment</td>
        <td class="f-val">{{ format_currency(doc.custom_projected_investment or 0) }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Projected sales price</td>
        <td class="f-val">{{ format_currency(doc.custom_projected_sales_price or 0) }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Projected equity</td>
        <td class="f-val">{{ format_currency(doc.custom_projected_equity or 0) }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Projected LTV</td>
        <td class="f-val">{{ fmt_pct(doc.custom_projected_ltv) }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Monthly Space Rent</td>
        <td class="f-val">{{ format_currency(doc.custom_monthly_space_rent or 0) }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Projected payoff</td>
        <td class="f-val">{{ doc.custom_projected_payoff or '' }}</td>
      </tr>
    </tbody>
  </table>
  {% endif %}

  <!-- ═══ KEY INFORMATION — SOLD VARIANT ═══ -->
  {% if doc.home_type == "Customer Sold" %}
  <table class="inv-items" style="margin-top: 16px !important;">
    <thead>
      <tr><th colspan="2">Key Information</th></tr>
    </thead>
    <tbody>
      <tr>
        <td class="f-lbl">Customer name</td>
        <td class="f-val">{{ buyer_name }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Escrow Company</td>
        <td class="f-val">{{ escrow_name }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Escrow Number</td>
        <td class="f-val">{{ hbr.escrow_number or '' }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Sales Price</td>
        <td class="f-val">{{ format_currency(hbr.selling_price) if hbr and hbr.selling_price else '' }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Loan-to-value</td>
        <td class="f-val">{% if hbr and hbr.selling_price and doc.requested_advance_amount %}{{ "%.0f" | format(doc.requested_advance_amount / hbr.selling_price * 100) }}%{% endif %}</td>
      </tr>
      <tr>
        <td class="f-lbl">Customer deposit</td>
        <td class="f-val">{{ format_currency(hbr.customer_deposit) if hbr and hbr.customer_deposit else '' }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Lender</td>
        <td class="f-val">{{ hbr.end_buyer_lender or '' }}</td>
      </tr>
      <tr>
        <td class="f-lbl">Projected payoff</td>
        <td class="f-val">{{ doc.custom_projected_payoff or '' }}</td>
      </tr>
    </tbody>
  </table>
  {% endif %}

  <div class="inv-div"></div>

  <!-- ═══ NOTES ═══ -->
  <div class="no-break">
    <div class="lbl" style="padding-bottom: 12px !important;">Notes:</div>
    {% if doc.custom_notes %}
    <div class="val" style="line-height: 1.5 !important;">{{ doc.custom_notes }}</div>
    {% endif %}
  </div>

  <div class="inv-div"></div>

  <!-- ═══ FOOTER ═══ -->
  <table>
    <tr>
      <td style="width: 50% !important; vertical-align: top !important;">
        <img src="/files/Icon.png" style="height: 25px !important; object-fit: contain !important; display: block !important; filter: brightness(0) !important;" alt="DCR">
      </td>
      <td style="width: 50% !important; text-align: right !important; vertical-align: top !important;">
        <div class="lbl">Contact</div>
        <div class="val">{{ company_doc.email or 'accounting@dealercapital.net' }}</div>
        <div class="val">{{ format_phone(company_doc.phone_no or '8004541116') }}</div>
      </td>
    </tr>
  </table>

</div>
